#!/usr/bin/env python3
"""
Verification-workbench tests A–I (brief 2026-11-02 'Verification Workbench' §09) on a COPY of the database.

  python3 -I tools/review_tests.py          # -> eval/review-tests-<date>.md ; exit 1 on any FAIL

A temporary root is built under tests/review/out/<date>/ (gitignored) with copies of plants/, relations.json, sources.json,
schema.json, ontology.json, synonyms.json, intent_map.json, eval/queries.json, brain/data/ and review/ai/; the tools run with
PLANTING_DB_ROOT pointing there, so the real database and the real event log are never touched. Every synthetic event carries
`payload.synthetic: true` and the reviewer id `test-run`. Results are what actually happened in that root.
"""
import json, os, shutil, subprocess, sys, importlib
from datetime import date

HERE = os.path.dirname(os.path.abspath(__file__)); REAL = os.path.dirname(HERE); TODAY = date.today().isoformat()
TEST = os.path.join(REAL, "tests", "review", "out", TODAY)
if os.path.exists(TEST): shutil.rmtree(TEST)
for d in ("plants", "eval", os.path.join("brain", "data"), os.path.join("review", "ai")): os.makedirs(os.path.join(TEST, d))
for f in ("relations.json", "sources.json", "schema.json", "ontology.json", "synonyms.json", "intent_map.json", "README.md"): shutil.copy(os.path.join(REAL, f), TEST)
shutil.copy(os.path.join(REAL, "eval", "queries.json"), os.path.join(TEST, "eval"))
for f in os.listdir(os.path.join(REAL, "plants")): shutil.copy(os.path.join(REAL, "plants", f), os.path.join(TEST, "plants"))
for f in os.listdir(os.path.join(REAL, "brain", "data")): shutil.copy(os.path.join(REAL, "brain", "data", f), os.path.join(TEST, "brain", "data"))
for f in ("queue.json", "checks.json"):
    if os.path.exists(os.path.join(REAL, "review", "ai", f)): shutil.copy(os.path.join(REAL, "review", "ai", f), os.path.join(TEST, "review", "ai"))
if os.path.isdir(os.path.join(REAL, "review", "ai", "assessments")): shutil.copytree(os.path.join(REAL, "review", "ai", "assessments"), os.path.join(TEST, "review", "ai", "assessments"))
os.environ["PLANTING_DB_ROOT"] = TEST; sys.path.insert(0, HERE)
for m in ("validate", "migrate_0_4", "merge_claims", "review_store", "review_apply", "ai_review"):
    if m in sys.modules: importlib.reload(sys.modules[m])
import review_store as RS, review_apply as RA, ai_review as AIR  # noqa: E402
J = lambda p: json.load(open(p, encoding="utf-8"))
results, out = {}, [f"# Verification-workbench tests A–I · {TODAY}", "", f"Generated by `python3 -I tools/review_tests.py` on a copy of the database at `{os.path.relpath(TEST, REAL)}` (gitignored). Synthetic events are marked `synthetic: true`, reviewer `test-run`; the real event log was not written.", ""]
def rec(t, ok, lines): results[t] = "PASS" if ok else "FAIL"; out.extend([f"## Test {t}", ""] + [f"- {l}" for l in lines] + [f"**{results[t]}**", ""])
def claim(cid):
    pid = cid.split(":")[0]; p = J(os.path.join(TEST, "plants", f"{pid}.json")); return next(c for c in p["claims"] if c["id"] == cid)
A = AIR.latest_assessments()
supported = [cid for cid, a in A.items() if a["result"] == "supported_by_source" and claim(cid).get("status") == "unverified"]
cid1 = supported[0] if supported else next(cid for cid in J(os.path.join(TEST, "review", "ai", "queue.json"))["rows"][0:1] and [J(os.path.join(TEST, "review", "ai", "queue.json"))["rows"][0]["claim_id"]])
cid2 = supported[1] if len(supported) > 1 else cid1

# A persistence
ev = RS.record_decision(claim(cid1), "request_evidence", "test-run", "test: persistence", ai_review_id=(A.get(cid1) or {}).get("review_id"))
ev["payload"]["synthetic"] = True
importlib.reload(RS); back = [e for e in RS.events(cid1) if e["event_id"] == ev["event_id"]]
rec("A", bool(back) and os.path.exists(RS.EVENTS), [f"decision event written to {os.path.relpath(RS.EVENTS, REAL)} and read back after a module reload: {bool(back)}", f"event id {ev['event_id']} · fingerprint {ev['fingerprint']}"])

# B traceability
a1 = A.get(cid1); lines = []
okB = True
if a1:
    okB &= a1["claim_id"] == cid1 and bool(a1.get("source_url")) and a1.get("fingerprint") == RS.fingerprint(claim(cid1)); lines.append(f"AI assessment {a1['review_id']} → claim {cid1} · source {a1['source_id']} {a1['source_url']} · locator {a1.get('locator')!r} · fingerprint matches current claim: {a1.get('fingerprint') == RS.fingerprint(claim(cid1))}")
else: lines.append("no AI assessment on file for the chosen claim (AI reviews still running)"); okB = False
okB &= back[0]["payload"]["ai_review_id"] == (a1 or {}).get("review_id") and back[0]["fingerprint"] == RS.fingerprint(claim(cid1)); lines.append(f"human event carries ai_review_id and the claim fingerprint: {back[0]['payload']['ai_review_id']} / {back[0]['fingerprint']}")
rec("B", okB, lines)

# C verification boundaries
before = claim(cid1).get("status"); nA = sum(1 for cid, a in A.items() if a["result"] == "supported_by_source")
rec("C", before == "unverified", [f"{nA} AI 'supported_by_source' assessments on file; claim {cid1} (AI supported) status is still '{before}' — no AI result changed a status", "apply refuses a non-mutating decision: " + str(not RA.plan(ev["event_id"])["ok"]) + f" ({RA.plan(ev['event_id']).get('reason')})"])

# D human disagreement
ev2 = RS.record_decision(claim(cid1), "dispute", "test-run", "test: reviewer disagrees with the AI — the page gives a different range", ai_review_id=(a1 or {}).get("review_id"), replaces=ev["event_id"]);
a_after = AIR.latest_assessments().get(cid1)
rec("D", a_after == a1 and ev2["payload"]["decision"] == "dispute" and ev2["payload"]["replaces_event"] == ev["event_id"], [f"dispute recorded against AI result '{(a1 or {}).get('result')}' with reason; AI record unchanged on disk: {a_after == a1}", f"event {ev2['event_id']} replaces {ev['event_id']} (both kept)"])

# E safe database update
r_apply = RA.apply(ev2["event_id"], "test-run", run_pipeline=False); c_now = claim(cid1)
ev3 = RS.record_decision(claim(cid2), "verify", "test-run", "test: verify", ai_review_id=(A.get(cid2) or {}).get("review_id"))
# stale: change the claim text after the decision, then try to apply
pid2 = cid2.split(":")[0]; pp = os.path.join(TEST, "plants", f"{pid2}.json"); p2 = J(pp)
for c in p2["claims"]:
    if c["id"] == cid2: c["text"] = c["text"] + " (edited after the decision)"
json.dump(p2, open(pp, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
r_stale = RA.apply(ev3["event_id"], "test-run", run_pipeline=False)
# invalid correction: categorical value outside the vocabulary
cid3 = next(cid for cid in A if claim(cid).get("value_kind") == "categorical" and claim(cid).get("status") == "unverified" and cid not in (cid1, cid2))
ev4 = RS.record_decision(claim(cid3), "propose_correction", "test-run", "test: bad correction", correction={"value": ["Not A Vocabulary Value"], "value_label": ["Not A Vocabulary Value"], "text": "corrected"})
snap = open(os.path.join(TEST, "plants", f"{cid3.split(':')[0]}.json"), encoding="utf-8").read(); r_bad = RA.apply(ev4["event_id"], "test-run", run_pipeline=False); same = open(os.path.join(TEST, "plants", f"{cid3.split(':')[0]}.json"), encoding="utf-8").read() == snap
# valid verify on a fresh claim
cid4 = next(cid for cid in supported if cid not in (cid1, cid2, cid3)) if len(supported) > 3 else cid2
ev5 = RS.record_decision(claim(cid4), "verify", "test-run", "test: verify ok", ai_review_id=(A.get(cid4) or {}).get("review_id"), locally_applicable=False); r_ok = RA.apply(ev5["event_id"], "test-run", run_pipeline=False)
c4 = claim(cid4); val = subprocess.run([sys.executable, "-I", os.path.join(HERE, "validate.py"), "--quiet"], env=dict(os.environ, PLANTING_DB_ROOT=TEST)).returncode
rec("E", r_apply["ok"] and c_now.get("status") == "disputed" and not r_stale["ok"] and "stale" in r_stale["reason"] and not r_bad["ok"] and same and r_ok["ok"] and c4.get("status") == "verified" and c4.get("verification_scope") in ("content", "statement") and val == 0,
    [f"dispute applied: {cid1} → {c_now.get('status')} (dispute_reason recorded)", f"stale apply refused: {r_stale.get('reason')}", f"invalid correction refused and file unchanged: {not r_bad['ok']} / {same} ({(r_bad.get('errors') or [r_bad.get('reason')])[0][:120]})", f"valid verify applied: {cid4} → {c4.get('status')} scope {c4.get('verification_scope')} verified_by {c4.get('verified_by')} review_events {c4.get('review_events')}", f"validator on the test root after the applies: exit {val}"])

# F history integrity
evs = RS.events(cid1); kinds = [e["kind"] for e in evs]
rec("F", len([e for e in evs if e["kind"] == "human_decision"]) == 2 and "decision_applied" in kinds and all("event_id" in e for e in evs), [f"{len(evs)} events for {cid1}: {kinds} — the replaced request_evidence decision is still there", f"total events in the test log: {len(RS.events())}; nothing deleted (append-only file)"])

# G graph consistency
r = subprocess.run([sys.executable, "-I", os.path.join(HERE, "pipeline.py"), "--quiet"], capture_output=True, text=True, env=dict(os.environ, PLANTING_DB_ROOT=TEST))
kg = J(os.path.join(TEST, "brain", "data", "kg.json")); kc = kg["claims"].get(cid4, {}); kd = kg["claims"].get(cid1, {})
rec("G", r.returncode == 0 and kc.get("status") == "verified" and kd.get("status") == "disputed", [f"pipeline on the test root: exit {r.returncode}", f"kg.json claim index: {cid4} status {kc.get('status')}, {cid1} status {kd.get('status')} — the graph reflects the applied decisions; kg.json was regenerated, not edited"])

# H privacy
ign = all(subprocess.run(["git", "check-ignore", "-q", f], cwd=REAL).returncode == 0 for f in ("review/events/review_events.jsonl", "review/ai/cache/x.txt", "inputs/survey/respondent_map.json", "inputs/survey/responses-2026-11-03.csv"))
srv = open(os.path.join(HERE, "review_server.py"), encoding="utf-8").read(); web = open(os.path.join(REAL, "review", "web", "index.html"), encoding="utf-8").read()
tracked = subprocess.run(["git", "ls-files"], cwd=REAL, capture_output=True, text=True).stdout.split()
leak = [f for f in tracked if f.startswith(("review/events/", "review/ai/cache/", "inputs/survey/")) and not f.endswith("README.md")]
import re as _re
pm = os.path.join(REAL, "inputs", "survey", "respondent_map.json"); ids = []
if os.path.exists(pm):   # the real response ids (private) must appear in no tracked file
    real_ids = [v["response_id"] for v in J(pm)["respondents"].values()]
    for rid in real_ids:
        ids += subprocess.run(["git", "grep", "-l", rid, "--", ".", ":!inputs/survey"], cwd=REAL, capture_output=True, text=True).stdout.split()
    ids = sorted(set(ids))
else: ids = ["(private map absent — id sweep skipped)"] if False else []
rec("H", ign and 'HTTPServer(("127.0.0.1"' in srv and "token" not in web.lower() and "api_key" not in web.lower() and not leak and not ids, [f"gitignore covers the event log, the page cache and the raw survey files: {ign}", f"server binds 127.0.0.1 only: {'HTTPServer((\"127.0.0.1\"' in srv}; no token / api_key strings in the web page: {'token' not in web.lower() and 'api_key' not in web.lower()}", f"tracked files under private paths: {leak or 'none'}", f"tracked files that contain survey-style UUIDs: {ids or 'none'}"])

# I semantic quality
rel = J(os.path.join(TEST, "relations.json"))["relations"]
r1_live = [x["id"] for x in rel if (x.get("rule") == "REL-R1" or (x.get("source_id") == "eflora" and x.get("relation_type") == "companion")) and x.get("status") != "retired"]
pairs_leak = [pp for pp in kg["plant_pairs"] for d in pp["direct_relations"] if d.get("verification") == "retired"]
surv = [c for p in os.listdir(os.path.join(TEST, "plants")) for c in J(os.path.join(TEST, "plants", p))["claims"] if str(c.get("source_id", "")).startswith("survey") and c.get("status") == "verified"]
scope_ok = all(c.get("verification_scope") == "statement" for c in surv)
shared_hab = sum(1 for pp in kg["plant_pairs"] if any(s.startswith(("habitat:", "bgc_zone:")) for s in pp["shared"]))
rec("I", not r1_live and not pairs_leak and scope_ok and shared_hab > 0, [f"live relations derived from shared habitat: {len(r1_live)} (retired ones kept: {sum(1 for x in rel if x.get('rule') == 'REL-R1')})", f"plant pairs sharing a habitat / zone concept node (indirect connection): {shared_hab} of {len(kg['plant_pairs'])}; retired relations shown as direct links: {len(pairs_leak)}", f"survey claims verified with scope 'statement' (a recorded statement, not verified botany): {sum(1 for c in surv if c.get('verification_scope') == 'statement')} of {len(surv)}"])

out.insert(4, "| test | result |\n|---|---|\n" + "\n".join(f"| {t} | {results[t]} |" for t in "ABCDEFGHI") + "\n")
path = os.path.join(REAL, "eval", f"review-tests-{TODAY}.md"); open(path, "w", encoding="utf-8").write("\n".join(out))
print(" ".join(f"{t}:{results[t]}" for t in "ABCDEFGHI"), "->", os.path.relpath(path, REAL))
sys.exit(1 if "FAIL" in results.values() else 0)
